#!/usr/bin/env python3
"""Audit completed original benchmark receipts without filling absent cells."""
import pathlib,json,hashlib,importlib.util,collections
BASE=pathlib.Path(__file__).resolve().parent;INC=BASE/'increment-r';OUT=BASE/'comparison/corrected-udp';OUT.mkdir(parents=True,exist_ok=True)
spec=importlib.util.spec_from_file_location('native_events',BASE/'native-events.py');native=importlib.util.module_from_spec(spec);spec.loader.exec_module(native)
cohorts=[];all_windows=[];failures=[];warnings=[]
for cell in sorted((INC/'evidence').glob('[0-9][0-9]-*')):
 result=json.loads((cell/'native-result.json').read_text());events,repairs,invalid=native.read_events(cell/'native-serial.log');values=[v for _,v in events];begin=next(v for v in values if v['event']=='begin');variant=begin['variant'];audits=[v for v in values if v['event']=='audit'];windows=[v for v in values if v['event']=='udp_open_window'];bad=[v for v in values if v['event']=='udp_window_fixture_failure'];zero=next((v for v in values if v['event']=='transport_drain_live_kernel'),None)
 checks={'native_passed':result['passed'],'whole_vm_budget':begin['cpus_online'].strip()=='0-3'and begin['cpus_possible'].strip()=='0-63','all_populations_start_end_audited':all(sum(v['actual_vhost_devices']==n for v in audits)==2 for n in [1,64,1024,4096,16384]),'independent_contexts':all(v['actual_vhost_devices']==v['independent_memory_contexts']for v in audits),'actual_cid_range':all(v['cid_last']-v['cid_first']+1==v['actual_vhost_devices']for v in audits),'expected_sockhash_keys':variant=='kernel'or all(v['backend']['occupied_sockhash']==v['actual_vhost_devices']*3 for v in audits),'expected_source_cookie_routes':variant=='kernel'or all(v['backend']['route_keys']==v['actual_vhost_devices']*2 for v in audits),'real_udp_bindings':all(v['udp_bindings']['independently_observed_owned_ip_port_tuples']==2*v['actual_vhost_devices']for v in audits),'all_64_open_conditions':len(windows)==64,'no_invalid_timing_or_actor_failure':not bad and all(v['valid_timing_comparison']for v in windows),'steady_counters_valid':all(v['guest_delivered']<=v['sent']and v['app_delivered']<=v['guest_sent']and not v['corrupt']and not v['boundary_violations']for v in windows),'all_population_pending_activity':all(v['participating_peers']==v['population']and v['maximum_inflight_peers']==v['population']for v in windows if v['initial_all_peer_burst']),'correctness_gate':any(v['event']=='correctness_gate_passed'for v in values),'credit_pressure_gate':sum(v['event']=='preflight_udp_credit_pressure'for v in values)==3,'all_posttraffic_settled':sum(v['event']=='posttraffic_settle'and not v['errors']for v in values)==5,'live_stock_zero':bool(zero and zero['confirmed_zero']and zero['usage']==0),'no_unrecoverable_uart_events':not invalid}
 cohorts.append({'run':cell.name,'variant':variant,'candidate':begin['corrected_candidate'],'checks':checks,'result':result,'uart_repairs':repairs,'source_metadata':'executed-source-manifest.json and executed-artifact-pins.json','offered':sum(v['offered']for v in windows),'sent':sum(v['sent']for v in windows),'guest_delivered_by_cutoff':sum(v['guest_delivered']for v in windows),'app_delivered_by_cutoff':sum(v['app_delivered']for v in windows),'deadline_loss_host_guest':sum(v['host_to_guest_loss']for v in windows),'deadline_loss_guest_host':sum(v['guest_to_host_loss']for v in windows),'posttraffic_late_validated':sum(v['validated_late_endpoint_messages']for v in values if v['event']=='posttraffic_settle')})
 for name,good in checks.items():
  if not good:failures.append({'run':cell.name,'check':name})
 all_windows.extend({'run':cell.name,**v}for v in windows)
# Kernel warnings retained verbatim as evidence, never rewritten out of originals.
import gzip
for cell in sorted((INC/'evidence').glob('[0-9][0-9]-*')):
 p=cell/'native-serial.log';text=p.read_text()if p.exists()else gzip.decompress(p.with_name(p.name+'.gz').read_bytes()).decode()
 for number,line in enumerate(text.splitlines(),1):
  if line.startswith('[')and any(token in line for token in ['clocksource: Long','WARNING:','BUG:','Oops:','Out of memory','soft lockup','hard LOCKUP']):warnings.append({'run':cell.name,'serial_line':number,'text':line})
(OUT/'kernel-warning-lines.json').write_text(json.dumps(warnings,indent=2))
# Source-language/provenance facts: no modified Rust BPF versus original k.
source={'udp_bpf_identical_to_original_k':(INC/'udp-bpf/src/main.rs').read_bytes()==(BASE/'increment-k/udp-bpf/src/main.rs').read_bytes(),'tcp_bpf_identical_to_original_k':(INC/'tcp-bpf/src/main.rs').read_bytes()==(BASE/'increment-k/tcp-bpf/src/main.rs').read_bytes(),'corrected_route_pins':json.loads((INC/'correction-provenance.json').read_text()),'upstream_pins':json.loads((INC/'upstream-pins.json').read_text()),'steady_window_sha256':hashlib.sha256((INC/'src/open_udp.rs').read_bytes()).hexdigest()}
receipt={'completed_cohorts':len(cohorts),'expected_cohorts':6,'valid_open_windows':len(all_windows),'expected_open_windows':384,'checks_failed':failures,'source':source,'cohorts':cohorts,'unsupported_traffic_cells':'1024/4096 payload0/59000 open-loop cells not run; full IPv6/65507/ordinary-guest composition not validated; exact module/BPF loader latency not independently timed','activity_meaning':'maximum_inflight_peers counts actually sent application requests awaiting reply; all-peer burst holds endpoint receive service until each peer has been offered one message. It is not a kernel queue occupancy count.','deadline_loss_meaning':'not delivered by original offering interval plus common bounded drain; queued late messages retained and validated outside steady timing, with separate CPU receipts'}
(OUT/'native-validation.json').write_text(json.dumps(receipt,indent=2));print(json.dumps({'cohorts':len(cohorts),'windows':len(all_windows),'failed_checks':failures}))
assert len(cohorts)==6 and len(all_windows)==384 and not failures
